#include <vector>
#include <cstddef>
#include <omp.h>

void gemv(std::vector<double> const& A,
          std::vector<double> const& x,
          std::vector<double> &y,
          size_t M,
          size_t N)
{
    // Ensure output size is correct
    if (y.size() != M) y.assign(M, 0.0);

    // Basic bounds guard (assumes caller intends valid sizes)
    if (M == 0 || N == 0) return;
    if (A.size() < M * N || x.size() < N) return;

    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(M); ++i) {
        const size_t row = static_cast<size_t>(i) * N;
        double sum = 0.0;
        for (size_t j = 0; j < N; ++j) {
            sum += A[row + j] * x[j];
        }
        y[static_cast<size_t>(i)] = sum; // each thread writes a distinct y[i]
    }
}
